    #[test]
    fn sparse_direct_uses_direct_path_after_first_iteration() {
        // Regression: SparseDirectCsc never set pattern_built, so its direct
        // CSC assembly path was dead code and every iteration re-ran COO
        // assembly. Pin the intended behavior: COO exactly once (pattern
        // discovery), direct accumulation for all later iterations.
        struct CountingProblem { coo_calls: usize, direct_calls: usize }
        impl LmProblem<f64> for CountingProblem {
            fn calc_cost(&mut self, x: &[f64]) -> f64 {
                (x[0] - 3.0) * (x[0] - 3.0) + (x[1] - 7.0) * (x[1] - 7.0)
            }
            fn calc_grad_hessian_dense(&mut self, _: &[f64], _: &mut [f64], _: &mut [f64]) -> f64 { unimplemented!() }
            fn calc_grad_hessian_band(&mut self, _: &[f64], _: &mut [f64], _: &mut [f64], _: usize) -> Result<f64, BandError> { unimplemented!() }
            fn calc_grad_hessian_sparse_direct(&mut self, x: &[f64], grad: &mut [f64], csc: &mut CscMatrix<f64>) -> f64 {
                self.direct_calls += 1;
                grad[0] = 2.0 * (x[0] - 3.0); grad[1] = 2.0 * (x[1] - 7.0);
                csc.vals.iter_mut().for_each(|v| *v = 0.0);
                csc.vals[csc.diag_pos[0]] += 2.0;
                csc.vals[csc.diag_pos[1]] += 2.0;
                self.calc_cost(x)
            }
            fn calc_grad_hessian_sparse_indexed(&mut self, _: &[f64], _: &mut [f64], _: &mut [f64], _: &[usize]) -> f64 { unimplemented!() }
            fn calc_grad_hessian_sparse(&mut self, x: &[f64], grad: &mut [f64], coo: &mut CooMatrix<f64>) -> f64 {
                self.coo_calls += 1;
                grad[0] = 2.0 * (x[0] - 3.0); grad[1] = 2.0 * (x[1] - 7.0);
                coo.clear();
                coo.push(0, 0, 2.0);
                coo.push(1, 1, 2.0);
                self.calc_cost(x)
            }
        }

        let mut problem = CountingProblem { coo_calls: 0, direct_calls: 0 };
        #[allow(deprecated)]
        let result = solve_sparse_direct_csc(&[0.0, 0.0], &mut problem, &LmConfig::default());
        assert!((result.x[0] - 3.0).abs() < 1e-6);
        assert!((result.x[1] - 7.0).abs() < 1e-6);
        assert_eq!(problem.coo_calls, 1, "COO assembly must run exactly once");
        assert!(problem.direct_calls >= 1,
            "direct CSC assembly must handle all iterations after the first \
             (got {} direct calls)", problem.direct_calls);
    }

    #[test]
    fn solver_reuse_across_solves_is_safe() {
        // Regression: reusing a solver across lm_solve calls used to panic
        // (index out of bounds) because the solver kept its cached position
        // map / symbolic factorization while lm_solve created a fresh empty
        // matrix. lm_solve now resets solver caches at entry, so a reused
        // solver behaves identically to a fresh one -- even when the second
        // problem has a different structure.
        struct QP;
        impl LmProblem<f64> for QP {
            fn calc_cost(&mut self, x: &[f64]) -> f64 {
                (x[0] - 3.0) * (x[0] - 3.0) + (x[1] - 7.0) * (x[1] - 7.0)
            }
            fn calc_grad_hessian_dense(&mut self, _: &[f64], _: &mut [f64], _: &mut [f64]) -> f64 { unimplemented!() }
            fn calc_grad_hessian_band(&mut self, _: &[f64], _: &mut [f64], _: &mut [f64], _: usize) -> Result<f64, BandError> { unimplemented!() }
            fn calc_grad_hessian_sparse_direct(&mut self, x: &[f64], grad: &mut [f64], csc: &mut CscMatrix<f64>) -> f64 {
                grad[0] = 2.0 * (x[0] - 3.0); grad[1] = 2.0 * (x[1] - 7.0);
                csc.vals.iter_mut().for_each(|v| *v = 0.0);
                csc.vals[csc.diag_pos[0]] += 2.0;
                csc.vals[csc.diag_pos[1]] += 2.0;
                self.calc_cost(x)
            }
            fn calc_grad_hessian_sparse_indexed(&mut self, x: &[f64], grad: &mut [f64], vals: &mut [f64], positions: &[usize]) -> f64 {
                grad[0] = 2.0 * (x[0] - 3.0); grad[1] = 2.0 * (x[1] - 7.0);
                vals.iter_mut().for_each(|v| *v = 0.0);
                vals[positions[0]] += 2.0;
                vals[positions[1]] += 2.0;
                self.calc_cost(x)
            }
            fn calc_grad_hessian_sparse(&mut self, x: &[f64], grad: &mut [f64], coo: &mut CooMatrix<f64>) -> f64 {
                grad[0] = 2.0 * (x[0] - 3.0); grad[1] = 2.0 * (x[1] - 7.0);
                coo.clear();
                coo.push(0, 0, 2.0);
                coo.push(1, 1, 2.0);
                self.calc_cost(x)
            }
        }
        // 3-variable problem with a coupling entry: different n AND
        // different pattern than QP.
        struct QP3;
        impl LmProblem<f64> for QP3 {
            fn calc_cost(&mut self, x: &[f64]) -> f64 {
                (x[0] - 1.0).powi(2) + (x[1] - 2.0).powi(2) + (x[2] - 3.0).powi(2) + (x[0] - x[2]).powi(2)
            }
            fn calc_grad_hessian_dense(&mut self, _: &[f64], _: &mut [f64], _: &mut [f64]) -> f64 { unimplemented!() }
            fn calc_grad_hessian_band(&mut self, _: &[f64], _: &mut [f64], _: &mut [f64], _: usize) -> Result<f64, BandError> { unimplemented!() }
            fn calc_grad_hessian_sparse_direct(&mut self, _: &[f64], _: &mut [f64], _: &mut CscMatrix<f64>) -> f64 { unimplemented!() }
            fn calc_grad_hessian_sparse_indexed(&mut self, x: &[f64], grad: &mut [f64], vals: &mut [f64], positions: &[usize]) -> f64 {
                grad[0] = 2.0 * (x[0] - 1.0) + 2.0 * (x[0] - x[2]);
                grad[1] = 2.0 * (x[1] - 2.0);
                grad[2] = 2.0 * (x[2] - 3.0) - 2.0 * (x[0] - x[2]);
                vals.iter_mut().for_each(|v| *v = 0.0);
                vals[positions[0]] += 4.0;
                vals[positions[1]] += 2.0;
                vals[positions[2]] += -2.0;
                vals[positions[3]] += 4.0;
                self.calc_cost(x)
            }
            fn calc_grad_hessian_sparse(&mut self, x: &[f64], grad: &mut [f64], coo: &mut CooMatrix<f64>) -> f64 {
                grad[0] = 2.0 * (x[0] - 1.0) + 2.0 * (x[0] - x[2]);
                grad[1] = 2.0 * (x[1] - 2.0);
                grad[2] = 2.0 * (x[2] - 3.0) - 2.0 * (x[0] - x[2]);
                coo.clear();
                coo.push(0, 0, 4.0);
                coo.push(1, 1, 2.0);
                coo.push(0, 2, -2.0);
                coo.push(2, 2, 4.0);
                self.calc_cost(x)
            }
        }

        let cfg = LmConfig::default();
        let mut solver = SparseFaer::new();
        // Same structure twice
        let r1 = lm_solve(&[0.0, 0.0], &mut solver, &mut QP, &cfg);
        let r2 = lm_solve(&[5.0, 5.0], &mut solver, &mut QP, &cfg);
        assert!((r1.x[0] - 3.0).abs() < 1e-6 && (r1.x[1] - 7.0).abs() < 1e-6);
        assert!((r2.x[0] - 3.0).abs() < 1e-6 && (r2.x[1] - 7.0).abs() < 1e-6);
        // Different structure with the same reused solver. Minimum of the
        // coupled quadratic is at (5/3, 2, 7/3) with cost 4/3.
        let r3 = lm_solve(&[0.0, 0.0, 0.0], &mut solver, &mut QP3, &cfg);
        assert!((r3.x[0] - 5.0 / 3.0).abs() < 1e-6, "x0={}", r3.x[0]);
        assert!((r3.x[1] - 2.0).abs() < 1e-6, "x1={}", r3.x[1]);
        assert!((r3.x[2] - 7.0 / 3.0).abs() < 1e-6, "x2={}", r3.x[2]);
        assert!((r3.end_cost - 4.0 / 3.0).abs() < 1e-9, "cost={}", r3.end_cost);

        // Same exercise for SparseDirectCsc (pattern_built flag)
        #[allow(deprecated)]
        let mut direct = SparseDirectCsc::new();
        let r4 = lm_solve(&[0.0, 0.0], &mut direct, &mut QP, &cfg);
        let r5 = lm_solve(&[5.0, 5.0], &mut direct, &mut QP, &cfg);
        assert!((r4.x[0] - 3.0).abs() < 1e-6);
        assert!((r5.x[1] - 7.0).abs() < 1e-6);
    }


    #[test]
    fn spd_band_guards_reject_nan_not_just_negative() {
        // Regression (B5): the SPD guards used `x <= 0.0`, which NaN
        // passes. A NaN on the band diagonal must fail the
        // factorization, not produce a NaN "solution" with a true
        // return. (The invert_spd_3x3 half of the original test left
        // with the deleted SparseSchur solver.)
        let kd = 1;
        let n = 3;
        let mut band = vec![0.0; (kd + 1) * n];
        for j in 0..n { band[kd + j * (kd + 1)] = 4.0; }
        band[kd + 1 * (kd + 1)] = f64::NAN;
        let mut b = vec![1.0; n];
        assert!(!solve_spd_band(n, kd, &mut band, &mut b),
            "NaN diagonal must fail the factorization");

        let mut band32 = vec![0.0f32; (kd + 1) * n];
        for j in 0..n { band32[kd + j * (kd + 1)] = 4.0; }
        band32[kd + 1 * (kd + 1)] = f32::NAN;
        let mut b32 = vec![1.0f32; n];
        assert!(!solve_spd_band_f32(n, kd, &mut band32, &mut b32),
            "NaN diagonal must fail the f32 factorization");
    }

    #[test]
    fn csc_symv() {
        // [4 1]  * [1] = [6]
        // [1 3]    [2]   [7]
        let mut coo = CooMatrix::<f64>::new(2);
        coo.push(0, 0, 4.0);
        coo.push(0, 1, 1.0);
        coo.push(1, 1, 3.0);
        let csc = coo.to_csc().unwrap();
        let mut y = vec![0.0; 2];
        csc.symv(&[1.0, 2.0], &mut y);
        assert!((y[0] - 6.0).abs() < 1e-12);
        assert!((y[1] - 7.0).abs() < 1e-12);
    }

    #[test]
    fn dense_vs_sparse_hessian_equal() {
        // 4-variable problem with off-diagonal coupling:
        // cost = (x0-1)^2 + (x1-2)^2 + (x2-3)^2 + (x3-4)^2 + (x0-x2)^2 + (x1-x3)^2
        // Dense hessian (symmetric):
        //   [4  0  -2  0]
        //   [0  4   0 -2]
        //   [-2 0   4  0]
        //   [0 -2   0  4]
        struct CoupledProblem;
        impl LmProblem<f64> for CoupledProblem {
            fn calc_cost(&mut self, x: &[f64]) -> f64 {
                (x[0]-1.0).powi(2) + (x[1]-2.0).powi(2) + (x[2]-3.0).powi(2) + (x[3]-4.0).powi(2)
                    + (x[0]-x[2]).powi(2) + (x[1]-x[3]).powi(2)
            }
            fn calc_grad_hessian_dense(&mut self, x: &[f64], g: &mut [f64], h: &mut [f64]) -> f64 {
                g[0] = 2.0*(x[0]-1.0) + 2.0*(x[0]-x[2]);
                g[1] = 2.0*(x[1]-2.0) + 2.0*(x[1]-x[3]);
                g[2] = 2.0*(x[2]-3.0) - 2.0*(x[0]-x[2]);
                g[3] = 2.0*(x[3]-4.0) - 2.0*(x[1]-x[3]);
                // Row-major 4x4
                h[0*4+0]=4.0; h[0*4+1]=0.0; h[0*4+2]=-2.0; h[0*4+3]=0.0;
                h[1*4+0]=0.0; h[1*4+1]=4.0; h[1*4+2]=0.0;  h[1*4+3]=-2.0;
                h[2*4+0]=-2.0;h[2*4+1]=0.0; h[2*4+2]=4.0;  h[2*4+3]=0.0;
                h[3*4+0]=0.0; h[3*4+1]=-2.0;h[3*4+2]=0.0;  h[3*4+3]=4.0;
                self.calc_cost(x)
            }
            fn calc_grad_hessian_band(&mut self, _: &[f64], _: &mut [f64], _: &mut [f64], _: usize) -> Result<f64, BandError> { unimplemented!() }
            fn calc_grad_hessian_sparse_direct(&mut self, _: &[f64], _: &mut [f64], _: &mut CscMatrix<f64>) -> f64 { unimplemented!() }
            fn calc_grad_hessian_sparse_indexed(&mut self, _: &[f64], _: &mut [f64], _: &mut [f64], _: &[usize]) -> f64 { unimplemented!() }
            fn calc_grad_hessian_sparse(&mut self, x: &[f64], g: &mut [f64], coo: &mut CooMatrix<f64>) -> f64 {
                g[0] = 2.0*(x[0]-1.0) + 2.0*(x[0]-x[2]);
                g[1] = 2.0*(x[1]-2.0) + 2.0*(x[1]-x[3]);
                g[2] = 2.0*(x[2]-3.0) - 2.0*(x[0]-x[2]);
                g[3] = 2.0*(x[3]-4.0) - 2.0*(x[1]-x[3]);
                coo.clear();
                // Upper triangle only
                coo.push(0, 0, 4.0);
                coo.push(0, 2, -2.0);
                coo.push(1, 1, 4.0);
                coo.push(1, 3, -2.0);
                coo.push(2, 2, 4.0);
                coo.push(3, 3, 4.0);
                self.calc_cost(x)
            }
        }

        let x = [0.0, 0.0, 0.0, 0.0];
        let n = 4;

        // Dense assembly
        let mut grad_dense = vec![0.0; n];
        let mut hessian = vec![0.0; n * n];
        CoupledProblem.calc_grad_hessian_dense(&x, &mut grad_dense, &mut hessian);

        // Sparse assembly
        let mut grad_sparse = vec![0.0; n];
        let mut coo = CooMatrix::new(n);
        CoupledProblem.calc_grad_hessian_sparse(&x, &mut grad_sparse, &mut coo);
        let csc = coo.to_csc().unwrap();

        // Gradients must match
        for i in 0..n {
            assert!((grad_dense[i] - grad_sparse[i]).abs() < 1e-12,
                "grad[{}]: dense={}, sparse={}", i, grad_dense[i], grad_sparse[i]);
        }

        // Convert sparse (upper triangle CSC) to dense and compare
        let mut sparse_as_dense = vec![0.0; n * n];
        for j in 0..n {
            for k in csc.col_ptr[j]..csc.col_ptr[j + 1] {
                let i = csc.row_idx[k] as usize;
                let v = csc.vals[k];
                sparse_as_dense[i * n + j] = v;
                if i != j { sparse_as_dense[j * n + i] = v; }
            }
        }

        for i in 0..n {
            for j in 0..n {
                assert!((hessian[i * n + j] - sparse_as_dense[i * n + j]).abs() < 1e-12,
                    "H[{},{}]: dense={}, sparse={}", i, j, hessian[i*n+j], sparse_as_dense[i*n+j]);
            }
        }

        // Also verify both solvers produce the same result. This
        // hand-written problem implements only the dense and COO paths,
        // so it exercises the explicit dense and COO-baseline entries.
        let config = LmConfig { abs_precision: 1e-10, max_iters: 100, initial_lambda: 0.001, ..Default::default() };
        let r_dense = solve_dense(&x, &mut CoupledProblem, &config);
        #[allow(deprecated)]
        let r_sparse = solve_sparse_coo(&x, &mut CoupledProblem, &config);
        for i in 0..n {
            assert!((r_dense.x[i] - r_sparse.x[i]).abs() < 1e-6,
                "x[{}]: dense={}, sparse={}", i, r_dense.x[i], r_sparse.x[i]);
        }
    }

    #[test]
    #[cfg(feature = "eigen")]
    fn sparse_eigen_quadratic() {
        struct QP;
        impl LmProblem<f64> for QP {
            fn calc_cost(&mut self, x: &[f64]) -> f64 {
                (x[0]-3.0)*(x[0]-3.0) + (x[1]-7.0)*(x[1]-7.0)
            }
            fn calc_grad_hessian_dense(&mut self, x: &[f64], g: &mut [f64], h: &mut [f64]) -> f64 {
                g[0]=2.0*(x[0]-3.0); g[1]=2.0*(x[1]-7.0);
                h[0]=2.0; h[1]=0.0; h[2]=0.0; h[3]=2.0;
                self.calc_cost(x)
            }
            fn calc_grad_hessian_band(&mut self,_:&[f64],_:&mut[f64],_:&mut[f64],_:usize)->Result<f64,BandError>{unimplemented!()}
            fn calc_grad_hessian_sparse_direct(&mut self,_:&[f64],_:&mut[f64],_:&mut CscMatrix<f64>)->f64{unimplemented!()}
            fn calc_grad_hessian_sparse_indexed(&mut self, x: &[f64], g: &mut [f64], vals: &mut [f64], pos: &[usize]) -> f64 {
                g[0]=2.0*(x[0]-3.0); g[1]=2.0*(x[1]-7.0);
                vals.iter_mut().for_each(|v| *v = 0.0);
                vals[pos[0]] += 2.0; vals[pos[1]] += 2.0;
                self.calc_cost(x)
            }
            fn calc_grad_hessian_sparse(&mut self, x: &[f64], g: &mut [f64], coo: &mut CooMatrix<f64>) -> f64 {
                g[0]=2.0*(x[0]-3.0); g[1]=2.0*(x[1]-7.0);
                coo.clear(); coo.push(0,0,2.0); coo.push(1,1,2.0);
                self.calc_cost(x)
            }
        }
        let r = solve_sparse_eigen(&[0.0,0.0], &mut QP,
            &LmConfig{abs_precision:1e-10, max_iters:100, initial_lambda:0.001, verbose:false, ..Default::default()});
        assert!((r.x[0]-3.0).abs()<1e-6, "x={}", r.x[0]);
        assert!((r.x[1]-7.0).abs()<1e-6, "y={}", r.x[1]);
        assert!(r.end_cost < 1e-10);
    }

    #[test]
    #[cfg(feature = "eigen")]
    fn sparse_eigen_coupled() {
        // 4-var coupled, compare with dense
        struct CP;
        impl LmProblem<f64> for CP {
            fn calc_cost(&mut self, x: &[f64]) -> f64 {
                (x[0]-1.0).powi(2)+(x[1]-2.0).powi(2)+(x[2]-3.0).powi(2)+(x[3]-4.0).powi(2)
                    +(x[0]-x[2]).powi(2)+(x[1]-x[3]).powi(2)
            }
            fn calc_grad_hessian_dense(&mut self, x: &[f64], g: &mut [f64], h: &mut [f64]) -> f64 {
                g[0]=2.0*(x[0]-1.0)+2.0*(x[0]-x[2]); g[1]=2.0*(x[1]-2.0)+2.0*(x[1]-x[3]);
                g[2]=2.0*(x[2]-3.0)-2.0*(x[0]-x[2]); g[3]=2.0*(x[3]-4.0)-2.0*(x[1]-x[3]);
                h[0]=4.0;h[1]=0.0;h[2]=-2.0;h[3]=0.0;
                h[4]=0.0;h[5]=4.0;h[6]=0.0;h[7]=-2.0;
                h[8]=-2.0;h[9]=0.0;h[10]=4.0;h[11]=0.0;
                h[12]=0.0;h[13]=-2.0;h[14]=0.0;h[15]=4.0;
                self.calc_cost(x)
            }
            fn calc_grad_hessian_band(&mut self,_:&[f64],_:&mut[f64],_:&mut[f64],_:usize)->Result<f64,BandError>{unimplemented!()}
            fn calc_grad_hessian_sparse_direct(&mut self,_:&[f64],_:&mut[f64],_:&mut CscMatrix<f64>)->f64{unimplemented!()}
            fn calc_grad_hessian_sparse_indexed(&mut self, x: &[f64], g: &mut [f64], vals: &mut [f64], pos: &[usize]) -> f64 {
                g[0]=2.0*(x[0]-1.0)+2.0*(x[0]-x[2]); g[1]=2.0*(x[1]-2.0)+2.0*(x[1]-x[3]);
                g[2]=2.0*(x[2]-3.0)-2.0*(x[0]-x[2]); g[3]=2.0*(x[3]-4.0)-2.0*(x[1]-x[3]);
                vals.iter_mut().for_each(|v| *v = 0.0);
                vals[pos[0]] += 4.0; vals[pos[1]] += -2.0;
                vals[pos[2]] += 4.0; vals[pos[3]] += -2.0;
                vals[pos[4]] += 4.0; vals[pos[5]] += 4.0;
                self.calc_cost(x)
            }
            fn calc_grad_hessian_sparse(&mut self, x: &[f64], g: &mut [f64], coo: &mut CooMatrix<f64>) -> f64 {
                g[0]=2.0*(x[0]-1.0)+2.0*(x[0]-x[2]); g[1]=2.0*(x[1]-2.0)+2.0*(x[1]-x[3]);
                g[2]=2.0*(x[2]-3.0)-2.0*(x[0]-x[2]); g[3]=2.0*(x[3]-4.0)-2.0*(x[1]-x[3]);
                coo.clear();
                coo.push(0,0,4.0); coo.push(0,2,-2.0);
                coo.push(1,1,4.0); coo.push(1,3,-2.0);
                coo.push(2,2,4.0); coo.push(3,3,4.0);
                self.calc_cost(x)
            }
        }
        let cfg = LmConfig{abs_precision:1e-10, max_iters:100, initial_lambda:0.001, verbose:false, ..Default::default()};
        let rd = solve(&[0.0;4], &mut CP, &cfg);
        let re = solve_sparse_eigen(&[0.0;4], &mut CP, &cfg);
        for i in 0..4 {
            assert!((rd.x[i]-re.x[i]).abs()<1e-6, "x[{}]: dense={}, eigen={}", i, rd.x[i], re.x[i]);
        }
    }

